from __future__ import unicode_literals

from functools import partial
import unittest
from ute_common_util.test.temp import path_to_resource
from ute_common_config_files.scfc.scfc import Scfc

path_to_resource = partial(path_to_resource, __name__)
DIST_NAME = 'MRBTS-1/BTSSCL-1/LCELL-1'


class TestParam(unittest.TestCase):

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_get_value(self, scfc_path):
        param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_param('existingParam')
        self.assertEqual(param.value, '123')

    @path_to_resource('resources/scfc/simple_param.xml')
    def test_set_value(self, scfc_path):
        param = Scfc(scfc_path).find_managed_object(DIST_NAME).find_param('existingParam')
        param.value = 'newValue'
        self.assertEqual(param.value, 'newValue')
        self.assertEqual(param.xml.text, 'newValue')

    @path_to_resource('resources/scfc/simple_param_duplicated.xml')
    def test_value_of_simple_duplicated_param(self, scfc_path):
        managed_object = Scfc(scfc_path).find_managed_object(DIST_NAME)
        param = managed_object.find_param('existingParam', param_value='2')
        self.assertEqual(param.value, '2')
        param.value = 'newValue'
        self.assertEqual(param.value, 'newValue')
        self.assertEqual(managed_object.find_param('existingParam', param_value='1').value, '1')
